∀ {C : Type} {inst : CategoryTheory.Category C} {X : CategoryTheory.SimplicialObject C}
  {s : X.Splitting} {X_1 : CategoryTheory.SimplicialObject C} {s_1 : X_1.Splitting},
  { X := X, s := s } = { X := X_1, s := s_1 } → X = X_1 ∧ s ≍ s_1

∀ {F : Type} [inst : Field F] {E : Type} [inst_1 : Field E] [inst_2 : Algebra F E]
  [FiniteDimensional F E] [IsGalois F E] {K : IntermediateField F E}
  {H : Subgroup Gal(E/F)}, IntermediateField.fixedField H = K ↔ K.fixingSubgroup = H
